/// <summary>
/// Data provider for the @TaxTransactionInquiry:HeaderNote report.
/// Extends <c>SrsReportDataProviderPreProcessTempDB</c> and populates the <c>ConDemoNoteReportPreTmp</c> temporary table.
/// </summary>
[
    SRSReportParameterAttribute(classStr(ConDemoNoteReportPreContract))
]
public class ConDemoNoteReportPreDP extends SrsReportDataProviderPreProcessTempDB
{
    ConDemoNoteReportPreTmp conDemoNoteReportPreTmp;

}

Method.Source:
/// <summary>
/// Returns the temporary table buffer used by the report dataset.
/// </summary>
/// <returns>The <c>ConDemoNoteReportPreTmp</c> table buffer.</returns>
[SRSReportDataSetAttribute(tableStr(ConDemoNoteReportPreTmp))]
public ConDemoNoteReportPreTmp getConDemoNoteReportPreTmp()
{
    select conDemoNoteReportPreTmp;
    return conDemoNoteReportPreTmp;
}

/// <summary>
/// Main data processing method. Populates the <c>ConDemoNoteReportPreTmp</c> temporary table
/// with report data based on the contract parameters.
/// </summary>
public void processReport()
{
    ConDemoNoteHeader noteHeader;

    delete_from conDemoNoteReportPreTmp;

    insert_recordset conDemoNoteReportPreTmp (NoteId, Subject)
        select NoteId, Subject from noteHeader;
}
